import type { ReactNode } from "react";

import type { ScreenSlot } from "@/components/tennantite/lib/screen-types";
import { PlayerInventory } from "@/components/tennantite/player-inventory";
import { ScreenPanel } from "@/components/tennantite/screen-panel";
import { RecipeBookButton } from "@/components/tennantite/lib/screen-parts";
import { ScreenItemSlot } from "@/components/tennantite/lib/screen-slot";
import { padSlots } from "@/components/tennantite/lib/screen-types";

const CRAFT_POSITIONS = [
  [29, 16],
  [47, 16],
  [65, 16],
  [29, 34],
  [47, 34],
  [65, 34],
  [29, 52],
  [47, 52],
  [65, 52],
] as const;

export interface CraftingScreenProps {
  className?: string;
  craftItems?: ScreenSlot[];
  craftResult?: ScreenSlot;
  hotbarItems?: ScreenSlot[];
  onRecipeBook?: () => void;
  onSlotClick?: (area: "craft" | "craft-result" | "hotbar" | "main", index: number) => void;
  selectedIndex?: number;
  title?: ReactNode;
}

/**
 * 工作台界面（规格 §6）：`container/crafting_table.png` 176×166。
 */
const EMPTY_CRAFT_ITEMS: ScreenSlot[] = [];
const EMPTY_HOTBAR_ITEMS: ScreenSlot[] = [];
export function CraftingScreen({
  className,
  craftItems = EMPTY_CRAFT_ITEMS,
  craftResult = null,
  hotbarItems = EMPTY_HOTBAR_ITEMS,
  onRecipeBook,
  onSlotClick,
  selectedIndex,
  title,
}: CraftingScreenProps) {
  const craft = padSlots(craftItems, 9);
  return (
    <ScreenPanel
      background="container/crafting_table.png"
      className={className}
      height={166}
      title={title}
      width={176}
    >
      {CRAFT_POSITIONS.map(([left, top], index) => (
        <ScreenItemSlot
          item={craft[index]}
          key={`${left}-${top}`}
          label={`craft-${index}`}
          left={left}
          onActivate={
            onSlotClick
              ? () => {
                  onSlotClick("craft", index);
                }
              : undefined
          }
          top={top}
        />
      ))}
      <ScreenItemSlot
        item={craftResult}
        label="craft-result-0"
        left={119}
        onActivate={
          onSlotClick
            ? () => {
                onSlotClick("craft-result", 0);
              }
            : undefined
        }
        size={26}
        top={30}
      />
      <RecipeBookButton left={5} onClick={onRecipeBook} top={34} />
      <PlayerInventory
        bare
        hotbarItems={hotbarItems}
        onSlotClick={onSlotClick}
        selectedIndex={selectedIndex}
      />
    </ScreenPanel>
  );
}
